package migrations

import "gorm.io/gorm"

// ScopeParticipationIdempotencyKey narrows the idempotency index to one voter.
//
// The index used to be (election_id, idempotency_key). A key is generated by the
// client, so two voters in the same election could in principle choose the same
// key; the second one would be handed the first voter's confirmation token.
// Scoping the index to (election_id, user_id, idempotency_key) removes that
// collision without weakening the one-ballot-per-voter constraint, which is a
// separate unique index.
//
// GORM cannot alter an existing index in place, so this drops and recreates it.
// The new index can never conflict on an existing row: (election_id, user_id)
// is already unique. Idempotent: safe to run on every start.
func ScopeParticipationIdempotencyKey(db *gorm.DB) error {
	switch db.Dialector.Name() {
	case "postgres", "sqlite":
	default:
		return nil
	}

	if err := db.Exec("DROP INDEX IF EXISTS idx_participation_idempotency").Error; err != nil {
		return err
	}
	return db.Exec(`
		CREATE UNIQUE INDEX IF NOT EXISTS idx_participation_idempotency
		ON voter_participations (election_id, user_id, idempotency_key)
	`).Error
}
